package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Category    string  `json:"category"`
	Price       float64 `json:"price"`
	InternalSKU string  `json:"internal_sku,omitempty"`
	SupplierKey string  `json:"supplier_key,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeOrderBy attempts to prevent injection in ORDER BY clauses
// by checking for common dangerous keywords
func sanitizeOrderBy(input string) string {
	dangerous := []string{"INSERT", "UPDATE", "DELETE", "DROP", "ALTER", "EXEC"}
	upper := strings.ToUpper(input)
	for _, kw := range dangerous {
		if strings.Contains(upper, kw) {
			return "id"
		}
	}
	return input
}

// searchProducts handles product search with sorting
// The category filter uses parameterized queries for safety
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortCol := r.URL.Query().Get("sort")
	order := r.URL.Query().Get("order")

	if category == "" {
		category = "all"
	}
	if sortCol == "" {
		sortCol = "name"
	}
	if order == "" {
		order = "ASC"
	}

	// Validate order direction
	if strings.ToUpper(order) != "ASC" && strings.ToUpper(order) != "DESC" {
		order = "ASC"
	}

	// Apply sanitization to sort column
	sortCol = sanitizeOrderBy(sortCol)

	var query string
	var rows *sql.Rows
	var err error

	if category == "all" {
		// Note: sort column cannot be parameterized in PostgreSQL
		query = fmt.Sprintf("SELECT id, name, category, price, internal_sku, supplier_key FROM products ORDER BY %s %s LIMIT 50", sortCol, order)
		rows, err = db.Query(query)
	} else {
		query = fmt.Sprintf("SELECT id, name, category, price, internal_sku, supplier_key FROM products WHERE category = $1 ORDER BY %s %s LIMIT 50", sortCol, order)
		rows, err = db.Query(query, category)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Category, &p.Price, &p.InternalSKU, &p.SupplierKey); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck endpoint for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
